import fs from "fs";
import path from "path";
import {
  S3Client,
  GetObjectCommand,
  PutObjectCommand,
  ListObjectsV2Command,
} from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import type { CBA, Provision, AnnotationRecord } from "./types";

// Static manifests generated by `npm run prepare-data`
import cbaManifest from "./cba-manifest.json";
import provisionList from "./provisions.json";

// ── S3 client (only constructed when bucket is configured) ───────────────────
const BUCKET = process.env.S3_BUCKET_NAME;
const REGION = process.env.AWS_REGION ?? "us-east-1";
let s3: S3Client | null = null;
function getS3(): S3Client {
  if (!s3) s3 = new S3Client({ region: REGION });
  return s3;
}

// ── CBA list ─────────────────────────────────────────────────────────────────
export function getAllCBAs(): CBA[] {
  return cbaManifest as CBA[];
}

export function getRandomCBA(): CBA {
  const all = getAllCBAs();
  return all[Math.floor(Math.random() * all.length)];
}

export function getRandomCBAExcluding(excludeKeys: string[]): CBA | null {
  const excluded = new Set(excludeKeys);
  const available = getAllCBAs().filter(
    (c) => !excluded.has(`${c.source}/${c.filename}`)
  );
  if (available.length === 0) return null;
  return available[Math.floor(Math.random() * available.length)];
}

// ── Provision dictionary ─────────────────────────────────────────────────────
export function getAllProvisions(): Provision[] {
  return provisionList as Provision[];
}

export function getRandomProvisions(n: number): Provision[] {
  const all = getAllProvisions();
  const fixed = all.find((p) => p.conceptId === "C_WAGE_BASE_RATE")!;
  const rest = all.filter((p) => p.conceptId !== "C_WAGE_BASE_RATE");
  // Fisher-Yates shuffle on the remaining provisions
  for (let i = rest.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [rest[i], rest[j]] = [rest[j], rest[i]];
  }
  return [fixed, ...rest.slice(0, n - 1)];
}

// ── PDF access ───────────────────────────────────────────────────────────────

export async function getPDFPresignedUrl(source: string, filename: string): Promise<string> {
  const key = `cbas/${source}/${filename}`;
  const command = new GetObjectCommand({ Bucket: BUCKET!, Key: key });
  return getSignedUrl(getS3(), command, { expiresIn: 900 });
}

export function getCBAFilePath(source: string, filename: string): string {
  const REPO_ROOT = path.resolve(process.cwd(), "..");
  const CBAS_DIR = path.join(REPO_ROOT, "data", "cbas");
  const resolved = path.resolve(CBAS_DIR, source, filename);
  if (!resolved.startsWith(CBAS_DIR + path.sep)) throw new Error("Invalid path");
  return resolved;
}

export function isS3Configured(): boolean {
  return !!BUCKET;
}

// ── Annotation output — S3 (production) ──────────────────────────────────────

export async function writeAnnotationToS3(
  prolificPid: string,
  record: AnnotationRecord
): Promise<void> {
  const key = `annotations/${prolificPid}/${record.cba_source}/${record.cba_filename}.json`;
  await getS3().send(
    new PutObjectCommand({
      Bucket: BUCKET!,
      Key: key,
      Body: JSON.stringify(record),
      ContentType: "application/json",
    })
  );
}

export async function getCompletedCBAsForPID(prolificPid: string): Promise<string[]> {
  const prefix = `annotations/${prolificPid}/`;
  const keys: string[] = [];
  let continuationToken: string | undefined;

  do {
    const response = await getS3().send(
      new ListObjectsV2Command({
        Bucket: BUCKET!,
        Prefix: prefix,
        ContinuationToken: continuationToken,
      })
    );
    for (const obj of response.Contents ?? []) {
      if (!obj.Key) continue;
      // Strip "annotations/{pid}/" prefix and ".json" suffix → "source/filename"
      const rel = obj.Key.slice(prefix.length);
      const cbaKey = rel.endsWith(".json") ? rel.slice(0, -5) : rel;
      if (cbaKey) keys.push(cbaKey);
    }
    continuationToken = response.IsTruncated ? response.NextContinuationToken : undefined;
  } while (continuationToken);

  return keys;
}

// ── Annotation output — local disk (dev fallback) ─────────────────────────────
const REPO_ROOT = path.resolve(process.cwd(), "..");
const ANNOTATIONS_PATH = path.join(REPO_ROOT, "data", "annotations", "human_annotations.jsonl");

export function appendAnnotationRecord(record: AnnotationRecord): void {
  try {
    const dir = path.dirname(ANNOTATIONS_PATH);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.appendFileSync(ANNOTATIONS_PATH, JSON.stringify(record) + "\n", "utf-8");
  } catch (err) {
    console.error("[submit] Could not write annotation to disk:", err);
  }
}
